#import <Foundation/Foundation.h>
#import <CoreWLAN/CoreWLAN.h>
#define G(p,k) [[p valueForKey: @k] longValue]
#define S(p,k,v) [p setValue: @(v) forKey: @k]
int main(void) { @autoreleasepool {
	for (int i = 0; i <= 8; i++) { CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; p.ssidData = [@"H" dataUsingEncoding: NSUTF8StringEncoding]; S(p,"captiveNetworkStatus",i); printf("status %d captive %d wasCaptive %d desc:%s\n", i, G(p,"captiveNetwork"), G(p,"wasCaptiveNetwork"), [[[[p description] componentsSeparatedByString: @"\n"] subarrayWithRange: NSMakeRange(1, 2)] componentsJoinedByString: @"|"].UTF8String); }
	for (int w = 0; w < 2; w++) for (int c = 0; c < 2; c++) { CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; p.ssidData = [@"H" dataUsingEncoding: NSUTF8StringEncoding]; S(p,"wasCaptiveNetwork",w); S(p,"captiveNetwork",c); printf("was %d cap %d -> status %ld captive %d was %d line:%s\n", w, c, G(p,"captiveNetworkStatus"), G(p,"captiveNetwork"), G(p,"wasCaptiveNetwork"), [[[p description] componentsSeparatedByString: @"\n"][1] UTF8String]); }
	int secs[] = { 0, 3, 4, 11, 13, 14 }; for (int k = 0; k < 6; k++) for (long sm = 0; sm <= 3; sm++) { CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; p.ssidData = [@"H" dataUsingEncoding: NSUTF8StringEncoding]; p.security = secs[k]; S(p,"shareMode",sm); printf("sec %d setShare %ld -> share %ld line:%s\n", secs[k], sm, G(p,"shareMode"), [[[p description] componentsSeparatedByString: @"\n"][17] UTF8String]); }
	for (long r = 0; r < 4; r++) { CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; p.ssidData = [@"H" dataUsingEncoding: NSUTF8StringEncoding]; p.security = 3; S(p,"shareMode",1); S(p,"userRole",r); printf("role %ld share %ld %s\n", r, G(p,"shareMode"), [[[p description] componentsSeparatedByString: @"\n"][17] UTF8String]); }
	{ CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; printf("nil ssid: desc line0 %s ident %s ssid %s\n", [[[p description] componentsSeparatedByString: @"\n"][0] UTF8String], [[p valueForKey: @"identifier"] UTF8String] ?: "nil", [[p ssid] UTF8String] ?: "nil"); printf("hash empty %d\n", (int)([p hash] == [[CWMutableNetworkProfile new] hash])); printf("eq empty %d\n", [p isEqual: [CWMutableNetworkProfile new]]); }
	{ CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; p.ssidData = [@"Long ssid with more than twenty four bytes in it" dataUsingEncoding: NSUTF8StringEncoding]; printf("%s\n", [[[p description] componentsSeparatedByString: @"\n"][0] UTF8String]); }
	{ CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; p.ssidData = [@"0123456789abcdefghijklmn" dataUsingEncoding: NSUTF8StringEncoding]; printf("%s\n", [[[p description] componentsSeparatedByString: @"\n"][0] UTF8String]); }
	{ CWMutableNetworkProfile *p = [CWMutableNetworkProfile new]; p.ssidData = [@"0123456789abcdefghijklmno" dataUsingEncoding: NSUTF8StringEncoding]; printf("%s\n", [[[p description] componentsSeparatedByString: @"\n"][0] UTF8String]); }
} return 0; }
